insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'organic', 'Functional group: Hydrocarbons', 'Hydrocarbons are a class of molecule that is defined by functional groups called hydrocarbyls that contain only carbon and hydrogen, but vary in the number and order of double bonds. Each one differs in type (and scope) of reactivity. There are also a large number of branched or ring alkanes that have specific names, e.g., tert-butyl, bornyl, cyclohexyl, etc. There are several functional groups that contain an alkene such as vinyl group, allyl group, or acrylic group. Hydrocarbons may form charged structures: positively charged carbocations or negative carbanions. Carbocations are often named -um. Examples are tropylium and triphenylmethyl cations and the cyclopentadienyl anion.', 'Wikipedia: Functional group', 'https://en.wikipedia.org/w/index.php?title=Functional_group&oldid=1380368598', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'organic' and body = 'Hydrocarbons are a class of molecule that is defined by functional groups called hydrocarbyls that contain only carbon and hydrogen, but vary in the number and order of double bonds. Each one differs in type (and scope) of reactivity. There are also a large number of branched or ring alkanes that have specific names, e.g., tert-butyl, bornyl, cyclohexyl, etc. There are several functional groups that contain an alkene such as vinyl group, allyl group, or acrylic group. Hydrocarbons may form charged structures: positively charged carbocations or negative carbanions. Carbocations are often named -um. Examples are tropylium and triphenylmethyl cations and the cyclopentadienyl anion.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'organic', 'Functional group: Groups containing halogens', 'Haloalkanes are a class of molecule that is defined by a carbon–halogen bond. This bond can be relatively weak (in the case of an iodoalkane) or quite stable (as in the case of a fluoroalkane). In general, with the exception of fluorinated compounds, haloalkanes readily undergo nucleophilic substitution reactions or elimination reactions. The substitution on the carbon, the acidity of an adjacent proton, the solvent conditions, etc. all can influence the outcome of the reactivity.', 'Wikipedia: Functional group', 'https://en.wikipedia.org/w/index.php?title=Functional_group&oldid=1380368598', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'organic' and body = 'Haloalkanes are a class of molecule that is defined by a carbon–halogen bond. This bond can be relatively weak (in the case of an iodoalkane) or quite stable (as in the case of a fluoroalkane). In general, with the exception of fluorinated compounds, haloalkanes readily undergo nucleophilic substitution reactions or elimination reactions. The substitution on the carbon, the acidity of an adjacent proton, the solvent conditions, etc. all can influence the outcome of the reactivity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'organic', 'Functional group: Groups containing oxygen', 'Compounds that contain C–O bonds each possess differing reactivity based upon the location and hybridization of the C–O bond, owing to the electron-withdrawing effect of sp²-hybridized oxygen (carbonyl groups) and the donating effects of sp³-hybridized oxygen (alcohol groups).', 'Wikipedia: Functional group', 'https://en.wikipedia.org/w/index.php?title=Functional_group&oldid=1380368598', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'organic' and body = 'Compounds that contain C–O bonds each possess differing reactivity based upon the location and hybridization of the C–O bond, owing to the electron-withdrawing effect of sp²-hybridized oxygen (carbonyl groups) and the donating effects of sp³-hybridized oxygen (alcohol groups).');
